//Basic Operation Data



void mokaSwitchOff(lv_event_t * e){
	setMokaStatus(0);
}

void preheatingOn(lv_event_t * e)
{
	setMokaStatus(1);
}

// Conditions (preheat, target >= 100 C) are checked inside calibrateBoiling().
void calibrate(lv_event_t * e)
{
	calibrateBoiling();
}

void boilingOn(lv_event_t * e)
{
	if(getMokaStatus() != 2){
		setMokaStatus(2);
	}
	else{
		skipBloom();
	}
}

void manualBloomPhase(lv_event_t * e)
{
	//setMokaStatus(2);
	setManualBloomTime(300.0);
}

// Adjusts the target of the current mode (heating or boiling) by delta C.
static void adjustTargetTemp(float delta)
{
	int status = getMokaStatus();
	if(status == 1){
		setTargetHeatingTemp(getTargetHeatingTemp() + delta);
	}
	else if(status == 2){
		setTargetBoilingTemp(getTargetBoilingTemp() + delta);
	}
}

void decreaseTargetTemp(lv_event_t * e)
{
	adjustTargetTemp(-1.0f);
}

void increaseTargetTemp(lv_event_t * e)
{
	adjustTargetTemp(1.0f);
}

void saveTargetTemp(lv_event_t * e){
	if(getMokaStatus() == 1){
		saveTargetHeatingTemp(getTargetHeatingTemp());
	}
	if(getMokaStatus() == 2){
		saveTargetBoilingTemp(getTargetBoilingTemp());
	}
}

